def get_token(self):
    """Read the next token.

    @rtype: string
    """
    while True:
        if self.pos >= len(self.text):
            return 'EOF'
        c = self.text[self.pos]
        if c in self.whitespace:
            self.pos += 1
            continue
        if c == ';':
            self.pos = self.text.find('\n', self.pos)
            if self.pos < 0:
                self.pos = len(self.text)
            return 'EOL'
        if c in self.special:
            self.pos += 1
            return c
        if c in self.alphanum:
            start = self.pos
            self.pos += 1
            while self.pos < len(self.text) and \
                  self.text[self.pos] in self.alphanum:
                self.pos += 1
            return self.text[start:self.pos]
        raise dns.exception.SyntaxError

